const CREDENTIAL_STORE='scholarion-credential-pipeline-r106';
let credentialModel;try{credentialModel=JSON.parse(localStorage.getItem(CREDENTIAL_STORE));}catch{}credentialModel ||= {automatic:false,attempts:[],notices:[]};
const credentialPrograms=programCatalog.filter(p=>p.id>=15&&p.id<=26).map(p=>({...p,issuer:'Scholarion Academy',status:'TBC',requiredCourses:[]}));
function saveCredentialModel(){localStorage.setItem(CREDENTIAL_STORE,JSON.stringify(credentialModel));}
async function credentialHash(s){return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s)))).map(x=>x.toString(16).padStart(2,'0')).join('');}
async function appendCredentialAttempt(entry){const prev=credentialModel.attempts.at(-1)?.hash||'GENESIS';const record={sequence:credentialModel.attempts.length+1,time:new Date().toISOString(),...entry,previous:prev};record.hash=await credentialHash(JSON.stringify(record));credentialModel.attempts.push(record);saveCredentialModel();}
async function checkCredentialLedger(){let prev='GENESIS';for(let i=0;i<credentialModel.attempts.length;i++){const {hash,...r}=credentialModel.attempts[i];if(r.sequence!==i+1||r.previous!==prev||await credentialHash(JSON.stringify(r))!==hash)return false;prev=hash;}return true;}
const credentialStages=['Eligibility: every required final course grade at C or better','Personalized PDF and QR code','Issuer-signed Open Badges 3.0 credential and baked image','Public verification and private-reason-free revocation list','Learner wallet, sharing and export','Immediate in-app notice; email held until connector verification','Server-controlled append-only issuance ledger'];
function credentialWallet(){return heading('My credentials','Scholarion Academy · Certificates of completion')+`<div class="card"><h2>No issued credentials yet</h2><p>Program course requirements are TBC. Sample activity scores do not establish completion, and no certificate or signed badge has been issued.</p>${btn('View issuance requirements','#credential-pipeline',true)}</div><section class="card"><h2>In-app notices</h2>${credentialModel.notices.map(n=>`<p>${esc(n)}</p>`).join('')||'<p>No issuance notices.</p>'}</section><p>Email delivery remains held until its connector is verified.</p>`;}
function pipelinePage(){return heading('Certificate issuance pipeline','Scholarion Academy · Release 106 integration readiness')+`<div class="two-col"><section class="card"><h2>One eligibility rule</h2><p>Every required course must have a final grade of C or better. C−, incomplete, missing, withdrawn and unapproved transfer grades do not qualify.</p><ol>${credentialStages.map(s=>`<li style="margin:12px 0">${s}</li>`).join('')}</ol><div class="callout">Issuance is blocked until approved course requirements, verified completion records, issuer identity/key, and a public verification service are connected. Local cryptographic demo keys would not establish Scholarion Academy’s identity.</div></section><section class="card"><h2>Check eligibility</h2><form id="credential-check"><label>Program<select name="program" style="width:100%;padding:12px;margin:12px 0">${credentialPrograms.map(p=>`<option value="${p.id}">#${p.id} ${esc(p.title)}</option>`).join('')}</select></label><p>Current source requirements: TBC. Refused attempts are recorded locally too.</p><button class="button">Check completion requirements</button></form><div id="credential-result" role="status"></div><h3>Automatic issuance</h3><label><input type="checkbox" disabled> Off by default</label><p>Only an authenticated registrar may enable this after the production pipeline is configured.</p></section></div><section class="card"><h2>Attempt ledger</h2><p>Local hash-chain integrity check; no edit/delete controls. Browser storage is mutable and can be rewritten or truncated, so this is not an immutable production ledger.</p><button class="button secondary" data-credential="verify">Check local integrity</button> <button class="button secondary" data-credential="export">Export attempt ledger</button><p id="ledger-result" role="status"></p><div class="table-scroll"><table><thead><tr><th>Time</th><th>Program</th><th>Outcome</th></tr></thead><tbody>${credentialModel.attempts.map(a=>`<tr><td>${esc(a.time)}</td><td>#${a.program}</td><td>${esc(a.outcome)}</td></tr>`).join('')||'<tr><td colspan="3">No attempts recorded.</td></tr>'}</tbody></table></div></section>${btn('Program build roadmap','#release-roadmap',true)}`;}
function releaseRoadmap(){return heading('Scholarion Academy program build roadmap','Twelve programs · Preserve every program · Six proposed releases')+`<section class="card"><h2>Source decisions</h2><ul><li>Build #15–#26 under Scholarion Academy.</li><li>Retire or merge none. #15, #16 and #26 need reviewed mutual-exclusion or module-waiver rules to prevent duplicate credit.</li><li>Dependencies on #1–#14 are TBC, including #25 and related waivers.</li><li>Nine replacement titles await the report; current titles remain working titles.</li></ul><p>The reported overlap percentages have not been independently verified.</p></section><section class="card"><h2>Proposed six-release sequence</h2>${[['107','Shared module library and #15'],['108','Proposed: #16 and #26, with overlap rules'],['109','Proposed: foundations #18, #19 and #21'],['110','Proposed: applied programs #20, #22 and #23'],['111','Proposed: pathways #17 and #24'],['112','Proposed: #25 and final cross-program review']].map(([r,s])=>`<p><strong>Release ${r}</strong> — ${s}</p>`).join('')}<p>Only the Release 107 starting scope came from your message. Later sequencing is a draft for review.</p></section><div class="agent-grid">${credentialPrograms.map(p=>`<article class="card"><h3>#${p.id} ${esc(p.title)}</h3><p>Scholarion Academy</p><p>Working title · Course requirements TBC</p>${btn('Source outline','#program/'+p.id,true)}</article>`).join('')}</div>`;}
const beforeCredentialRender=render;
render=function(){const route=location.hash.slice(1);if(['credentials','credential-pipeline','admin/credentials','release-roadmap'].includes(route)){const body=route==='credentials'?credentialWallet():route==='release-roadmap'?releaseRoadmap():pipelinePage();document.getElementById('app').innerHTML=integratedShell(route,body,model.role);decorateRole(model.role);bind();document.title='Scholarion Academy credentials · Scholarion';}else beforeCredentialRender();};
let credentialBusy=false;
document.addEventListener('submit',async e=>{if(e.target.id!=='credential-check')return;e.preventDefault();if(credentialBusy)return;credentialBusy=true;try{const p=credentialPrograms.find(x=>x.id===Number(new FormData(e.target).get('program')));const result=CredentialRules.eligibility(p,[]);await appendCredentialAttempt({program:p.id,outcome:result.eligible?'Eligible — issuance pending configuration':'Refused — requirements TBC',reasons:result.reasons});credentialModel.notices.unshift('Completion check for program #'+p.id+' could not issue a certificate: requirements are TBC.');saveCredentialModel();render();document.getElementById('credential-result').textContent=result.reasons.join(' ');}finally{credentialBusy=false;}});
document.addEventListener('click',async e=>{const a=e.target.closest('[data-credential]')?.dataset.credential;if(a==='verify')document.getElementById('ledger-result').textContent=await checkCredentialLedger()?'Stored hash chain is consistent. This cannot detect complete rewriting or tail deletion without a trusted external anchor.':'Integrity mismatch detected. Do not trust this local ledger.';if(a==='export')download('scholarion-local-credential-attempts.json',JSON.stringify(credentialModel,null,2),'application/json');});
render();

